INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62609159', 62609159, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Sekretariat Jenderal Komdigi', 'Annual Tools Web Vulnerability Scanner', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 210198000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '( 1, unit, @ 210198000 )', '1. Annual Tools Web Vulnerability Scanner ( 1, unit, @ 210198000 );', '1. Tool harus memiliki kemampuan Automated Scanner dengan spesifikasi minimal: 1. Jenis Lisensi: Enterprise Edition (bukan versi Community/Free). 2. Cakupan Scan: Mendukung Network Scanning (IP based) dan Web Application Scanning. 3. Database Kerentanan: Memiliki database vulnerability yang terupdate secara real-time atau harian (lebih dari 50.000+ checks). 4. Fitur Utama: a. Discovery Asset (OS Detection, Port Scanning, Service Detection). b. Configuration Auditing (cisbenchmark compliance). c. Malware Detection integration. d. Mendukung CVSS v3/v4 scoring. 5. Pelaporan: Dapat menghasilkan report dalam berbagai format (PDF, CSV, XML) yang dapat dikustomisasi (Executive Summary & Technical Detail). 6. Deployment: Mendukung On-Premise atau Hybrid. Tool pendukung pengujian manual/eksploitasi dengan spesifikasi minimal: a. Kapabilitas: Intersepsi traffic HTTP/HTTPS, modifikasi request/response, dan automated crawling. 1. Fitur Khusus: a. Advanced Scanner untuk mendeteksi kerentanan web kompleks (SQLi, XSS, DOM-based vulnerabilities). b. Payload Generator untuk pengujian intrusi. c. Fitur kolaborasi proyek (Project file sharing). d. Dukungan ekstensi/plugin tambahan. 8. Standar Acuan: Mendukung pengujian berdasarkan OWASP Top 10', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 706343);
