INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62642335', 62642335, 'analyze_legacy', 'Kota Dumai', 'kabkota', 'DINAS KOMUNIKASI, INFORMATIKA, STATISTIK DAN PERSANDIAN', 'Belanja Kawat/Faksimili/Internet/TV Berlangganan', 'Jasa Lainnya', 'E-Purchasing', 'Riau, Dumai (Kota)', 1084496000, 'December 2025', 'APBD', 1, 1, '12 Bulan', 'Belanja Bandwith Jaringan Internet Internasional Dedicated', 'Spesifikasi : 1000 Mbps Target / sasaran yang ingin dicapai dalam kegiatan ini adalah Penyediaan akses Internet MIX (IX & IIX) dengan Kapasitas 1000 Mbps dengan jaminan Bandwidth Dedicated 1:1 via Fiber Optik dengan Sasaran: 1. Menyediakan Link Metro antara NOC, Kantor BPKAD dan MPP. 2. Menyediakan 1 link FO Backhaul ke Pusat Komputasi DISKOMINFOTIKSAN KOTA DUMAI. 3. Tersedianya Koneksi Jaringan Internet terhadap 10 Puskesmas dan 7 Kecamatan; 4. Manajemen Bandwitdh terpusat di Dinas Komunikasi, Informatika, Statistik dan Persandian Kota Dumai; 5. Tersedianya 1 unit Startlink di Kelurahan Marginal; 6. Bandwitdh ratio CIR (Committed Information Rate) 1:1 upstream dan downstream dengan sifat koneksi dedicated (non share/koneksi clear channel); 7. Media Akses menggunakan FO (Fiber Optic); 8. Koneksi akhir menggunakan Optical Network Transmition (ONT)dan Ethernet (RJ45); 9. Minimum ketersediaan Service layer Availability (SLA) minimal 99,2% (714 Jam 15 Menit) dalam sebulan (720 Jam ) dengan masa kewajaran apabila internet down/mati sebesar 0,08%/ 5 jam 45 menit (pembulatan 6 jam/bulan) setiap bulanya dan mendapatkan laporan performance dan penggunaan (MRTG) jika SLA berkurang dari nilai tersebut dapat digunakan sebagai pengurang pembayaran pekerjaan kepada penyedia jasa layanan internet; 10. Fasilitas Layanan tenaga ahli atau engineer professional yang siap melayani dan memantau selama 24 jam x 7 hari dalam seminggu; 11. Batas Maksimal apabila terjadi down time pada layanan internet maksimal 3% dalam waktu setahun (akumulasi dalam waktu setahun); 12. Penyedia harus memiliki POP (Point of Presense) atau yang terdekat dengan Pemerintah Kota Dumai; 13. Penyedia harus memiliki kantor yang berdomisili di Kota Dumai; 14. Penyedia harus memiliki insfrastruktur yang sudah terkoneksi diwilayah Kota Dumai; 15. Media koneksi/Backbone koneksi jaringan Bandwitdh menggunakan Fiber Optik; 16. Menghubungkan Bandwitdh ke Pusat Komputasi DISKOMINFOTIKSAN; 17. Mengikutsertakan pelatihan Teknis pengelolaan Network Management System bagi ASN/Tim Teknis Dinas Komunikasi, Informatika, Statistik dan Persandian Kota Dumai; 18. Menyediakan Link Metro MPP-Satlantas; 19. Bersedia memfasilitasi jaringan temporary yang dipergunakan untuk kegiatan Pemerintah Kota Dumai; 20. Sudah termasuk single gateway trafik domestik', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 707012);
