INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62500262', 62500262, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Video Tutorial / Animasi Aplikasi Layanan Publik Tahap 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 74074500, 'December 2025', 'APBD', 1, 1, '6 OB', 'pembuatan skenario video tutorial sesuai dengan buku manual ataupun alur bisnis proses yang dialami oleh pengguna aplikasi - pemilihan ilustrasi sebagai pendukung ditujukan untuk mempermudah pengguna dalam memahami video tutorial yang akan dibuat. Ilustrasi pendukung digunakan sebagai bahan uji terhadap draft skenario yang akan dibuat sebelum diproduksi - proses perekaman dengan menggunakan aplikasi yang tersedia guna menjelaskan proses yang terjadi diaplikasi yang dibuat video tutorialnya - melakukan proses editing atau penyuntingan setelah perekaman audio/visual ke komputer, untuk memilah bagian-bagian yang dianggap tidak perlu dapat dibuang. dan kemudian dilakukan penambahan animasi, efek suara,atau unsur lain - melakukan proses rendering setelah proses edit, kemudian file ditransfer menjadi format tertentu sesuai kebutuhan - desain infografis aplikasi – aplikasi yang dikembangkan, seperti aplikasi baru maupun penambahan modul di aplikasi eksisting', 'DESAIN GRAFIS TINGKAT II : Video Tutorial / AnimasiGrafis/Fotographer/Editor Video/Script Writer CAD/CAM Operator, yaitu S1Teknologi Informasi/Sistem Informasi/Informatika/Manajemen Informatika/Komunikasi Visual dengan kualifikasi: - Pria/Wanita usia maksimal 40 tahun - Pendidikan minimal S1 Teknologi Informasi/Sistem Informasi/Informatika/Manajemen Informatika/Komunikasi Visual atau sejenis - Menguasai Adobe Premier, Adobe Ilustratotr, Adobe Photoshop, Adobe After Effect - Inovatif, Kreatif, bersedia menerima tantangan baru - Menguasai Video Tutorial / Animasi grafis, video editing dan motion graphic - Memiliki keahlian Video Tutorial / Animasi terkini - Dapat mengoperasikan Komputer - Diutamakan memiliki Sertifikat Nasional (BNSP) bidang keahlian Video Tutorial / Animasi Grafis - Memiliki perangkat kerja untuk pembuatan video tutorial - Bersedia bekerja di lokasi Dinas Komunikasi dan Informatika selama kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 707286);
