INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62498878', 62498878, 'analyze_legacy', 'Kota Balikpapan', 'kabkota', 'UPTD-RUMAH SAKIT UMUM DAERAH', 'Penyediaan Jasa Supir Ambulance', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Timur, Balikpapan (Kota)', 253260000, 'December 2025', 'APBD', 1, 1, '9 Bulan', 'Melaksanakan pelayanan pengemudian ambulans secara aman, cepat, dan bertanggung jawab dalam rangka mendukung pelayanan kesehatan dan kegawatdaruratan pasien sesuai standar operasional prosedur (SOP) RSUD Beriman Balikpapan.', 'a. Empat orang sopir, masing masing untuk shift pagi, sore dan malam dan satu orang libur; b. Satu orang sopir operasional dengan jam kerja reguler dan bertugas untuk ,menggantikan supir ambulance saat ada kegiatan tambahan dengan persetujuan RSUD; c. Sopir yang terlatih disiplin, mempunyai ketrampilan mengemudi yang baik dan memiliki SIM B1; d. Bila ada sopir yang cuti atau tidak bisa masuk kerja, penyedia jasa wajib mencari ganti dengan sopir lain yang bekerja di RSUD Beriman Balikpapan; e. Bersedia melaksanakan tugas tambahan diluar jam kerja seperti tugas tim mini ICU; f. Apabila tenaga sopir melaksanakan tugas tambahan diluar jam kerja, maka kompensasi (lemburan) akan dibebankan kepada penyedia; g. Bertanggung jawab atas mobil ambulance, menjaga kebersihannya serta semua peralatan yang ada di dalamnya; h. Memeriksa kondisi ambulance setiap bertugas agar siap untuk di operasikan; i. Melaporkan kerusakan atau kehilangan peralatan kepada koordinator atau kepala ruangan IGD untuk di ambil tindakan agar semua ambulance siap di operasikan dan dalam kondisi yang optimal; j. Semua tenaga sopir diberikan Gaji Sesuai UMK Tahun 2024 dan BPJS Serta JHT dan diberikan THR serta diberikan seragam guna melaksanakan tugasnya k. Berpenampilan rapi, tidak bertato dan tidak bertindik; l. Dalam menjalankan tugasnya, para sopir wajib menggunakan APD sesuai standar dan disediakan oleh penyedia jasa; (dipastikan lagi yang menyediakan APD dari perusahaan penyedia atau RSUD Beriman) m. Masing-masing tenaga sopir ambulance membuat laporan harian kegiatan untuk dilaporkan setiap akhir bulan. n. Masing-masing tenaga sopir ambulance mengikuti pertemuan evaluasi Unit kerja/Instalasi yang membawahi unit ambulance.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 708043);
