INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62500409', 62500409, 'analyze_legacy', 'Kota Balikpapan', 'kabkota', 'UPTD-RUMAH SAKIT UMUM DAERAH', 'Penyediaan Jasa Pengamanan Kantor', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Timur, Balikpapan (Kota)', 2994120000, 'December 2025', 'APBD', 1, 1, '12 Bulan', 'Melaksanakan pengamanan lingkungan rumah sakit yang meliputi penjagaan, pengawasan, pengendalian akses, patroli area dalam dan luar gedung, pengaturan lalu lintas internal, penanganan gangguan keamanan dan ketertiban, serta dukungan pengamanan kegiatan rumah sakit guna menciptakan situasi yang aman, tertib, dan kondusif sesuai SOP dan ketentuan yang berlaku di RSUD Beriman Balikpapan', 'A. Persyaratan Tenaga Kerja (Jasa Lainnya) 1. Manager Keamanan a. Pria, usia 25-50 tahun; dibuktikan dengan KTP b. Min. D4/S1 sederajat, dibuktikan dengan ijazah c. Memiliki sertifikat Gada Utama; d. Memiliki pengalaman kerja, minimal sebagai petugas keamanan selama 3 (tiga) tahun. Dibuktikan dengan referensi dari tempat kerja Pada saat penyerahan dan penandatanganan SPPBJ, wajib menyerahkan: a. Surat keterangan kerja; b. Fotokopi kartu BPJS Kesehatan dan BPJS Tenaga Kerja; c. Surat keterangan sehat, bebas narkoba dari rumah sakit, SKCK (diserahkan pada saat penyerahan SPPBJ); d. Sertifikat Pencegahan dan Pengendalian Infeksi (PPI), Bantuan Hidup Dasar (BHD) yang dikeluarkan oleh instansi Kesehatan; e. Sertifikat Gada Utama; f. Memiliki kartu tanda anggota (KTA) pengamanan yang masih berlaku tanda anggota pengamanan yang masih berlaku. 2. Supervisor Keamanan a. Pria usia 24-40 tahun; dibuktikan dengan KTP b. Minimal SLTA/ sederajat; dibuktikan dengan ijazah c. Memiliki sertifikat Gada Madya; d. Memiliki pengalaman kerja, minimal sebagai petugas keamanan selama 2 (dua) tahun dibuktikan dengan referensi dari tempat kerja. Pada saat penyerahan dan penandatanganan SPPBJ, wajib menyerahkan: a. Surat keterangan kerja; b. Fotokopi kartu BPJS Kesehatan dan BPJS Tenaga Kerja; c. Surat keterangan sehat, bebas narkoba dari rumah sakit, SKCK; d. Sertifikat Gada Madya; e. Sertifikat Pencegahan dan Pengendalian Infeksi (PPI), Bantuan Hidup Dasar (BHD) yang dikeluarkan oleh instansi Kesehatan; f. Memiliki kartu tanda anggota pengamanan (KTA) yang masih berlaku. 3. Security Pelaksana a. Usia 19-40 tahun; dibuktikan dengan KTP; b. Untuk wanita, tidak sedang dalam keadaan hamil, dibuktikan dengan surat keterangan yang diserahkan saat penandatangan SPBBJ; c. Pendidikan minimal SLTA/ SMK Sederajat dibuktikan dengan ijazah ; d. Memiliki sertifikat Gada Pratama. e. Pengalaman Kerja minimal 1 tahun sebagai petugas keamanan, dibuktikan dengan referensi dari tempat kerja. Pada saat penyerahan dan penandatanganan SPPBJ, wajib menyerahkan: a. Surat keterangan kerja; b. Fotokopi kartu BPJS Kesehatan dan BPJS Tenaga Kerja; c. Surat keterangan sehat, bebas narkoba dari rumah sakit, SKCK (diserahkan pada saat penyerahan SPPBJ); d. Sertifikat Pencegahan dan Pengendalian Infeksi (PPI), Bantuan Hidup Dasar (BHD) yang dikeluarkan oleh instansi Kesehatan; e. Sertifikat Gada Pratama; f. Memiliki kartu tanda anggota (KTA) pengamanan yang masih berlaku . B. Kualifikasi Penyedia Barang/Jasa 1. Surat izin : Ijin Usaha yang masih berlaku untuk izin usaha yang diterbitkan oleh Lembaga OSS yang telah memenuhi Komitmen dan Berlaku Efektif atau Perizinan Berusaha berbasis resiko yang diterbitkan oleh Lembaga OSS Bidang Pekerjaan : KBLI 80100 Aktivitas Keamanan Swasta Kualifikasi usaha : Kecil atau Non Kecil; 2. Mempunyai Nomor Induk Berusaha (NIB); 3. Memiliki Nomor Pokok Wajib Pajak (NPWP) dan Memiliki status valid keterangan Wajib Pajak berdasrkan hasil Konfirmasi Status Wajib Pajak. 4. Berbentuk Badan Hukum dan didirikan sesuai Ketentuan Peraturan Perundang – undangan serta bergerak di bidang Usaha Penyediaan Jasa Pekerja Buruh; 5. Memiliki izin operasional dari instansi yang bertanggung jawab di bidang ketenagakerjaan Provinsi tempat pelaksanaan pekerjaan ( Untuk izin usaha yang belum OSS); 6. Memiliki bukti wajib lapor ketenagakerjaan di perusahaan yang masih berlaku yang dikeluarkan oleh Disnaker di wilayah Kalimantan Timur atau melalui WLKP secara Online; 7. Secara hukum mempunyai kapasitas untuk mengikatkan diri pada kontrak; 8. Mempunyai Badan Usaha Jasa Pengamanan (BPUJ) golongan Usaha Jasa Penyediaan Tenaga Pengamanan dari instansi yang berwenang ; 9. Memiliki sertifikat SMK3 / OHSAS 18001 / ISO 45001; 10. Memiliki sertifikat ISO Manajemen Mutu 9001 : 2015; 11. Telah terdaftar Kepesertaan BPJS Kesehatan dan Ketenagakerjaan. 12. Memiliki pengalaman : a. Penyediaan barang pada divisi yang sama paling kurang1 (satu) pekerjaan dalam kurun waktu 1 (satu) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak;dan b. Penyediaan barangsekurang-kurangnya dalam kelompok (grup) yang sama paling kurang 1 (satu) pekerjaan dalam kurun waktu 3 (tiga) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. c. untuk usaha kecil/koperasi yang mengikuti paket pengadaan untuk usaha nonkecil, memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir sebesar paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran. Penyedia dengan kualifikasi usaha kecil yang baru berdiri kurang dari 3 (tiga) tahun dan belum memiliki pengalaman dikecualikan dari ketentuan pengalaman sebagaimana dimaksud pada butir 1) huruf a) dan b) untuk paket pengadaan dengan nilai sampai dengan paling banyak Rp2.500.000.000,00 (dua miliar lima ratus juta rupiah). C. Pengendalian Mutu a. Penyedia jasa wajib menyediakan tenaga pengendalian mutu untuk memeriksa hasil kerja SDM dan membuat laporan harian. b. Membuat Standar Prosedur Operasional (SPO) yang telah disetujui oleh KPA.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 708161);
