INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62500682', 62500682, 'analyze_legacy', 'Majelis Permusyawaratan Rakyat', 'central', 'SEKRETARIAT JENDERAL', 'Pengadaan Jasa Outsourcing', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota) | Jawa Barat, Bandung (Kota) | Jawa Barat, Bandung (Kota)', 30892147000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '3 Paket', 'Pengadaan Jasa Outsourcing di Lingkungan Sekretariat Jenderal MPR RI, dengan penempatan di beberapa wilayah antara lain : Lingkungan Kantor Sekretariat Jenderal MPR RI, Rumah Dinas Pimpinan dan Sekretariat Jenderal, Gedung Merdeka dan Mess Bandung. 1. Pengadaan Jasa Outsourcing Tata Graha ( 1, Pkt, @ 12.351.746.000 ); 2. Pengadaan Jasa Outsourcing Teknisi dan Pengemudi ( 1, Pkt, @ 9.018.934.000 ); 3. Pengadaan Jasa Outsourcing Pengamanan ( 1, Pkt, @ 9.521.467.000 );', 'Supervisor Housekeeping sebanyak 1 (satu) orang Spesifikasi : a. Pendidikan minimal D3 semua jurusan; b. Memiliki sertifikat kompetensi skema supervisor; c. Pengalaman: minimal 3 (tiga) tahun dibidangnya; d. Usia : 25 – 35 tahun e. Memiliki surat keterangan sehat dari dokter dibuktikan sebelum kontrak; f. Memiliki jiwa kepemimpinan, berpenampilan baik, dan ber-attitude tinggi; g. Kemampuan sesuai dengan bidangnya masing-masing: 1) Mampu membuat RAB 2) Membuat laporan harian, mingguan, dan bulanan 3) Menguasai MS Office Housekeeping sebanyak 92 (sembilan puluh dua) orang, dengan penempatan di Lingkungan Sekretariat Jenderal MPR RI sebanyak 69 orang, Rumah Dinas Pimpinan MPR RI sebanyak 18 orang, Mess bandung dan Gedung Merdeka sebanyak 5 orang Spesifikasi : a) Pendidikan: minimal SMP/SMA/STM/SMK; b) Memiliki surat keterangan sehat dari dokter dibuktikan sebelum kontrak; c) Berpenampilan baik dan ber-attitude tinggi; d) Diutamakan bisa bekerja sebagai tim; e) Usia : 20 – 60 tahun Pramusaji Kantor sebanyak 12 (dua belas) orang Spesifikasi : a. Pendidikan: minimal SMA/STM/SMK perhotelan dan atau punya pengalaman kerja di hotel sebagai pramusaji; b. Memiliki surat keterangan sehat dari dokter dibuktikan sebelum kontrak; c. Berpenampilan baik, berattitude tinggi, dan good looking; d. Diutamakan bisa bekerja sebagai tim; Teknisi sebanyak 27 (dua puluh tujuh) orang, dengan rincian sebagai berikut : 1. Supervisor MEP sebanyak 2 orang Spesifikasi : 1. Pendidikan minimal D3 Teknik Mesin/Teknik Elektro 2. Memiliki sertifikat K3 Listrik yang berlaku dari Kemenaker 3. Pengalaman: minimal 3 (Tiga) tahun sebagai first level supervisor dalam proyek pengelolaan gedung; 4. Usia : 25 – 35 tahun 5. Memiliki surat keterangan sehat dari dokter dibuktikan sebelum kontrak;. 2. Teknisi Elektrikal sebanyak 6 orang Spesifikasi : 1) Pendidikan: minimal SMP/SMA/STM/SMK jurusan Listrik/Elektronika/ Otomasi Industri/Mesin/Elektro 2) Mampu membedakan tegangan listrik, membaca blueprint dan wiring diagram, serta tracking kabel 3) Pengalaman: minimal 3 (Tiga) tahun sebagai teknisi Gedung di bidang maintenance Instalasi kelistrikan Arus Kuat (Trafo, Genset, UPS, dan Panel Listrik) 4) Usia : 20 – 45 Tahun 3. Teknisi Mekanikal sebanyak 6 orang Spesifikasi : 1) Pendidikan: minimal SMP/SMA/STM/SMK jurusan Listrik/Mesin/ elektro. 2) Mempunyai kendaraan pribadi (motor) dan SIM aktif untuk tugas Teknis area Rumah Dinas MPR (Rudin Kemang, Rudin Kemanggisan, Rudin Cilandak, Rudin Jl. Denpasar Raya Kuningan dan Rudin Widya Candra) 3) Familiar dengan Sistem Tata Udara Gedung (AC VRV, AC Single (Split Wall, Split Dak, Casette), FCU, Sistem AHU, Chiler (Watercold & Aircold), exhaust fan) dan Sistem Pompa Gedung dan Rumah (Air Bersih, Diesel, Jockey dll), Hydrant minimal salah dua dari beberapa bidang tersebut 4) Mampu menggunakan alat service AC (Steam AC, Vacum AC, Manipold, Tang Amper, Peralatan Las Ringan dengan tabung Oksigen/Asetilin dan peralatan pendukung lainnya ) 5) Mengerti kelistrikan dasar (Arus Listrik, Daya Listrik, Voltase Listrik) 6) Pengalaman: minimal (tiga) tahun, khusus lulusan SMP minimal pengalaman 5 (lima) sebagai teknisi Gedung. 7) Usia : 20 – 40 Tahun 4. Teknisi Elektronika sebanyak 2 orang Spesifikasi : 1) Pendidikan: Minimal SMK jurusan DKV/Multimedia/Animasi/ Listrik/Ototronika 2) Mampu mengoperasikan mixer, Delegate, Speaker, Videotron/LED, Public Speaker, TV dan Telepon minimal salah satu dari beberapa bidang tersebut 3) Pengalaman: minimal 2 (dua) tahun sebagai teknisi 4) Usia : 20 – 40 Tahun 5. Teknisi Plumbing sebanyak 3 orang Spesifikasi : 1) Pendidikan: minimal SMP/SMA/STM/SMK jurusan Listrik/Mesin/ elektro/Sipil 2) Keahlian dalam instalasi dan pemeliharaan serta perbaikan ringan asesories sanitasi (kran, shower, sipon, flexible hose, floor drain dll), pipa air bersih, air kotor dan saluran pembuangan 3) Pengalaman: minimal 2 (dua) tahun sebagai teknisi plumbing 4) Usia : 20 – 45 tahun 6. Teknisi Sipil sebanyak 5 orang Spesifikasi : 1) Pendidikan: minimal SMP/SMA/STM/SMK diutamakan jurusan Listrik/Mesin/ Sipil/SMA; 2) Pengalaman minimal 2 (dua) tahun sebagai teknisi Gedung; 3) Diutamakan memiliki keahlian dan pengetahuan dalam pembangunan/perawatan/pemeliharaan bangunan; 4) Diutamakan bisa bekerja sebagai tim; 5) Usia : 20 – 48 tahun 7. Teknisi IT sebanyak 3 orang Spesifikasi : 1) Pendidikan: minimal SMP/SMA/STM/SMK jurusan IT/komputer/multimedia; 2) Menguasai keahlian hardware, software, system jaringan (LAN), multimedia, dan internet; 3) Pengalaman: minimal 2 (dua) tahun sebagai teknisi computer; Pengemudi sebanyak 41 (empat puluh satu) orang Spesifikasi : 1) Pendidikan: minimal SMP/SMA/SMK/Sederajat; 2) Pengalaman: minimal 1 (satu) tahun sebagai pengemudi 3) Mempunyai SIM dan masih berlaku 4) Usia 20 sd 45 tahun Pengadaan tenaga outsourcing sebanyak 75 orang dengan rincian sebagai berikut : 1. Koordinator Lapangan sebanyak 1 orang 2. Komandan Regu sebanyak 5 orang 3. Anggota Pengamanan sebanyak 69 orang', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 2, 708384);
