INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63167410', 63167410, 'analyze_legacy', 'Kementerian Pertahanan', 'central', 'LANTAMAL V SURABAYA TNI AL', 'Belanja Barang Persediaan Barang Konsumsi Urikkes Werving Catam pria I Lantamal V TA 2026', 'Barang', 'E-Purchasing', 'Jawa Timur, Surabaya (Kota)', 439560000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, 'Satu Paket', 'Urikkes Werving dilaksanakan dengan harapan setiap gejala penyakit dapat diketahui secara dini sehingga kondisi kesehatan calon Prajurit TNI Angkatan Laut terjaga. Hasil urikkes tersebut akan menjadi acuan dan dapat ditindak lanjuti terutama bagi calon Prajurit dengan hasil urikkes kurang baik. Pada kondisi demikian urikkes werving akan berperan optimal dalam menyiapkan personel agar selalu berada dalam kondisi prima secara fisik dan setiap saat untuk mengemban tugas. Selain itu untuk meningkatkan sumber daya manusia dalam pelaksanaan urikkes diperlukan peningkatan pengetahuan melalui pendidikan dan latihan agar pelaksanaan urikkes dapat lebih optimal.', 'Penerima manfaat dari pelaksanaan pengadaan bekkes urikkes werving adalah calon prajurit TNI Angkatan Laut Kodaeral V dalam rangka pemenuhan personel yang berkualitas untuk melaksanakan tugas dan tanggung jawab sesuai dengan spektrum penugasannya', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 708587);
