INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62643886', 62643886, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Ketahanan Pangan dan Peternakan', 'Belanja Jasa Tenaga Keamanan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bandung (Kota)', 571653453, 'December 2025', 'APBD', 1, 1, '1 Tahun', 'Ruang lingkup Pekerjaan Jasa Tenaga Keamanan pada Kegiatan Penyediaan Jasa Penunjang Urusan Pemerintahan Daerah Sub Kegiatan Penyediaan Jasa Pelayanan Umum Kantor Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat, meliputi: Seluruh area gedung yang ada pada Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat yaitu sebanyak 2 gedung yang terletak di Jl. Kawaluyaan Indah Raya No. 6 Kota Bandung dan Jl. Ir. H. Juanda No. 358 Kota Bandung. Ruang lingkup kerja antara lain sebagai berikut : a. Melaksanakan patroli pengamanan dilingkungan kantor Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat. b. Melaksanakan pengamanan gedung dan lingkungan sesuai dengan pos-pos yang telah ditentukan dilingkungan kantor Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat. c. Melaksanakan patroli pengamanan ke lingkungan komplek perumahan yang berdampingan dengan Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat d. Membantu pelaksanaan mematikan dan menyalakan lampu-lampu penerangan serta peralatan yang menggunakan listrik pada ruang-ruang perkantoran sesuai kebutuhan jam kerja dengan berkoordinasi dengan pengguna gedung dan lingkungan Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat. e. Membantu dengan melaporkan terkait kondisi penerangan, sistem pengaman, yang mengalami gangguan/tidak normal kepada Sub Bagian Kepegawaian, Umum dan Kehumasan pada Sekretariat Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat f. Melakukan koordinasi dengan Sub Bagian Kepegawaian, Umum dan Kehumasan pada Sekretariat Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat apabila terjadi permasalahan yang timbul akibat padamnya listrik PLN. g. Melaksanakan pengamanan/pengawalan kegiatan-kegiatan tertentu yang dilaksanakan di lingkungan Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat. h. Membantu pengaturan keluar masuk kendaraan dari dan ke wilayah Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat termasuk membantu pengaturan menyeberang jalan karyawan/masyarakat dari dan ke wilayah Dinas Ketahanan Pangan dan Peternakan Provinsi Jawa Barat. i. Memahami dan mahir dalam penggunaan drill tongkat dan drill borgol. j. Mengetahui posisi penempatan dan mampu menggunakan alat pemadam kebakaran bila terjadi kebakaran.', 'a. Memiliki sertifikat garda pratama yang dikeluarkan dari Kepolisian Republik Indonesia b. Satuan Pengamanan yang dipekerjakan berlatar belakang pendidikan minimal SMA dan sederajat. c. Perlengkapan dan alat bantu', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 709048);
